   [140]={next_id=141, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="阴影中传来缓慢的、清脆的鼓掌声。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_213.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [141]={next_id=142, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="反应很快，很警觉。", msg_color="", msg_size=0, talker="？？？", audio="", img="arts/ui/bg/story/storybg_213.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214_2", 0, 0, -22, 219.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [142]={next_id=143, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="一个穿着黑袍的人影从实验室深处缓缓走出来。兜帽压得很低，遮住了半张脸，只露出一个苍白的下巴和微微弯起的嘴角。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_213.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214_2", 0, 0, -22, 219.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [143]={next_id=144, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="早就发现有人躲在暗处了。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_213.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214_2", 0, 0, -22, 219.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [144]={next_id=145, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="不愧是余烬的家主和……莱斯坦斯的链尉官。", msg_color="", msg_size=0, talker="黑袍人", audio="", img="arts/ui/bg/story/storybg_213.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214_2", 0, 0, -22, 219.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [145]={next_id=146, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你竟然知道我？是从什么时候暴露的？", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_213.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214_2", 0, 0, -22, 219.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [146]={next_id=147, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="尽管经过乔装打扮，但在救下那个小女孩时的身手与气质，还是让我认出来了。", msg_color="", msg_size=0, talker="黑袍人", audio="", img="arts/ui/bg/story/storybg_213.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214_2", 0, 0, -22, 219.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [147]={next_id=148, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="果然是在那时候吗……", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_213.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214_2", 0, 0, -22, 219.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [148]={next_id=149, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="既然知道我们，想用这种小手段留下我们可没那么容易。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_213.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [149]={next_id=150, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="猎人在狩猎时，依靠的可不仅仅只有手中的猎枪。", msg_color="", msg_size=0, talker="黑袍人", audio="", img="arts/ui/bg/story/storybg_213.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214_2", 0, 0, -22, 219.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [150]={next_id=151, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="猎物的疲惫、恐惧、乃至逃脱后的大意，都可以成为猎人的武器。", msg_color="", msg_size=0, talker="黑袍人", audio="", img="arts/ui/bg/story/storybg_213.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214_2", 0, 0, -22, 219.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [151]={next_id=152, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="所以，你们最好再想想。从踏进这间实验室的那一刻起，你们真的看到“全部”了吗？", msg_color="", msg_size=0, talker="黑袍人", audio="", img="arts/ui/bg/story/storybg_213.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214_2", 0, 0, -22, 219.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [152]={next_id=153, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="就在这时，一柄匕首突然从你的视野盲区中刺出，直取你的后心。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_213.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [153]={next_id=154, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="袭击者出手的角度毒辣刁钻，匕首闪着寒芒以极快的速度袭来，距离你的身体不过一个呼吸的距离。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_213.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
